export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const [collapsed, setCollapsed]   = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const { plan, rawPlan, loading: planLoading, userEmail: planEmail, isTrialing, trialEndsAt } = usePlan();
  const userEmail = planEmail ?? '';
  const [score, setScore]           = useState<number | null>(null);
  // b8a1: the personal-context score — the pill relabels itself "AI Name
  // Recognition Score" on personal pages but showed the BUSINESS score.
  const [personalScore, setPersonalScore] = useState<number | null>(null);
  const [clientChecked, setClientChecked] = useState(false);
  const [pendingFixCount, setPendingFixCount] = useState(0);

  // Phase 2 — pending auto-generated fix count for the Fix Engine badge.
  useEffect(() => {
    let alive = true;
    fetch('/api/fixes/pending-count')
      .then(r => r.json())
      .then(d => { if (alive) setPendingFixCount(Number(d?.count) || 0); })
      .catch(() => {});
    return () => { alive = false; };
  }, []);
  const path   = usePathname();
  const router = useRouter();

  // E1: If this user is an agency CLIENT (has a row in agency_clients keyed by
  // client_user_id), they must land on the CLIENT dashboard — not the agency or
  // standard dashboard. Agency OWNERS (agency_user_id) are unaffected.
  useEffect(() => {
    let cancelled = false;
    async function checkClient() {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session) { if (!cancelled) setClientChecked(true); return; }
        // Already inside the client area — nothing to do.
        if (path.startsWith('/dashboard/client')) { if (!cancelled) setClientChecked(true); return; }
        const { data: clientRow } = await supabase
          .from('agency_clients')
          .select('id')
          .eq('client_user_id', session.user.id)
          .maybeSingle();
        if (cancelled) return;
        if (clientRow) {
          router.replace('/dashboard/client');
          return;
        }
      } catch {
        // Never trap the user on the loading screen if the lookup fails
        // (e.g. table missing on a fresh env) — fall through and render.
      }
      if (!cancelled) setClientChecked(true);
    }
    checkClient();
    return () => { cancelled = true; };
  }, [path, router]);

  async function handleSignOut() {
    await supabase.auth.signOut();
    router.push('/');
  }

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!session) return;
      supabase
        // ax8r: exclude personal-name scans — a personal_pro scan's score
        // used to show in the business sidebar.
        .from('rankall_scans')
        .select('overall_score')
        .eq('user_id', session.user.id)
        // .neq() drops rows whose intent_type is NULL (most legacy business
        // scans); keep them explicitly.
        .or('intent_type.neq.personal_pro,intent_type.is.null')
        .order('created_at', { ascending: false })
        .limit(1)
        .single()
        .then(({ data }) => { if (data) setScore(data.overall_score); });
      // b8a1: the personal score, loaded separately — the pill's label
      // must match the number it shows. No personal scan → stays null →
      // the pill honestly shows "—" on personal pages.
      supabase
        .from('rankall_scans')
        .select('overall_score')
        .eq('user_id', session.user.id)
        .eq('intent_type', 'personal_pro')
        .order('created_at', { ascending: false })
        .limit(1)
        .single()
        .then(({ data }) => { if (data) setPersonalScore(data.overall_score); });
    });
  }, []);

  const isAdmin  = isAdminUser(userEmail);
  const planCfg  = getPlanConfig(plan);

  // 14ypkw1d4xk: admins default to full (enterprise) access. The plan-switcher
  const agencyPlan = isAgencyPlan(plan);

  // Agency redirect: send agency users to agency command center
  useEffect(() => {
    if (planLoading) return;
    if (agencyPlan && path === '/dashboard') {
      router.replace('/dashboard/agency');
    }
  }, [agencyPlan, path, planLoading, router]);

  // rawPlan, not their elevated enterprise access.
  const navKey = normalizePlan(isAdmin ? rawPlan : plan);
  // Path-aware override: the Personal Brand pages always show the Personal Brand
  // sidebar/branding, regardless of the underlying plan — otherwise a business
  // or admin user (plan → 'business') sees the Local Business shell on them.
  const isPersonalPage = !!path && (
    path.startsWith('/dashboard/personal-brand') ||
    path.startsWith('/dashboard/personal') ||
    path.startsWith('/dashboard/ai-pitch')
  );
  const effectiveNavKey = isPersonalPage ? 'personal_pro' : navKey;
  // ax8r: the ADMIN section was dead code — this layout only wraps
  // /dashboard/*, so path never starts with /admin here and the section
  // never rendered. (Admin pages have their own layout.)
  // b01u: only link pages the plan can open — the same gated-path map +
  // planConfig dashboardPages the proxy enforces (lib/dashboardAccess), so
  // no nav link bounces to /pricing. Filtered by the user's real plan (the
  // Personal-page override only changes which sidebar shape is shown).
  const accessCfg = getPlanConfig(navKey);
  const sections: NavSection[] = (NAV_STRUCTURE[effectiveNavKey] ?? NAV_STRUCTURE.free)
    .map(section => ({ ...section, items: section.items.filter(item => canOpenDashboardPath(item.href, accessCfg)) }))
    .filter(section => section.items.length > 0);

  const truncateEmail = (email: string) => {
    if (email.length <= 24) return email;
    const [local, domain] = email.split('@');
    return `${local.slice(0, 10)}…@${domain}`;
  };

  const NavItem = ({ item }: { item: NavLink }) => {
    const active = path === item.href;
    return (
      <Link
        href={item.href}
        onClick={() => setMobileOpen(false)}
        style={{
          display: 'flex', alignItems: 'center', gap: 10,
          padding: collapsed ? '11px 0' : '9px 14px',
          justifyContent: collapsed ? 'center' : 'flex-start',
          borderRadius: active ? '0 8px 8px 0' : 10, textDecoration: 'none',
          background: active ? 'linear-gradient(90deg, rgba(124,58,237,0.10), transparent)' : 'transparent',
          borderLeft: active ? '3px solid #7c3aed' : '3px solid transparent',
          marginBottom: 3, transition: 'all 0.15s',
          color: active ? '#7c3aed' : GRAY,
        }}
      >
        <span style={{ fontSize: 16, flexShrink: 0 }}>{item.icon}</span>
        {!collapsed && <span style={{ fontSize: 13, fontWeight: active ? 700 : 600 }}>{item.label}</span>}
        {!collapsed && item.href === '/dashboard/fix' && pendingFixCount > 0 && (
          <span style={{ background: '#7c3aed', color: '#fff', borderRadius: 10, padding: '1px 7px', fontSize: 11, fontWeight: 700, marginLeft: 'auto' }}>
            {pendingFixCount}
          </span>
        )}
      </Link>
    );
  };

  const GroupHeader = ({ title }: { title: string }) => (
    collapsed ? (
      <div style={{ height: 1, background: BORDER, margin: '10px 6px' }} />
    ) : (
      <p style={{ fontSize: 10, fontWeight: 700, color: LGRAY, textTransform: 'uppercase', letterSpacing: '0.08em', margin: '14px 6px 6px' }}>
        {title}
      </p>
    )
  );

  const NavGroups = () => (
    <>
      {sections.map((section, gi) => (
        <div key={section.group ?? `g${gi}`}>
          {section.group && <GroupHeader title={section.group} />}
          {section.items.map((item, i) => <NavItem key={`${item.href}-${i}`} item={item} />)}
        </div>
      ))}
    </>
  );

  const Sidebar = () => (
    <div style={{ width: collapsed ? 60 : 220, flexShrink: 0, background: SIDEBAR, borderRight: `1px solid ${BORDER}`, height: '100vh', position: 'sticky', top: 0, display: 'flex', flexDirection: 'column', transition: 'width 0.2s', overflow: 'hidden' }}>

      {/* Logo row */}
      <div style={{ padding: '16px 12px 0', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: collapsed ? 'center' : 'space-between', paddingBottom: 16, borderBottom: `1px solid ${BORDER}`, marginBottom: 16 }}>
          {!collapsed && (
            <Link href="/" style={{ textDecoration: 'none', display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src="/rankall-logo-dark.png" alt="RankAll" width={110} height={22} style={{ height: 22, width: 'auto', display: 'block' }} />
            </Link>
          )}
          {!collapsed && (
            <button
              onClick={handleSignOut}
              style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 11, color: LGRAY, fontWeight: 600, padding: 0, flexShrink: 0, whiteSpace: 'nowrap', marginRight: 8 }}
              onMouseEnter={e => (e.currentTarget.style.color = '#DC2626')}
              onMouseLeave={e => (e.currentTarget.style.color = LGRAY)}
            >
              Sign out
            </button>
          )}
          <button
            onClick={() => setCollapsed(c => !c)}
            style={{ background: 'none', border: `1.5px solid ${BORDER}`, borderRadius: 7, width: 28, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: GRAY, fontSize: 12, flexShrink: 0 }}
          >
            {collapsed ? <svg viewBox="0 0 256 512" width="12" height="12" fill="currentColor" aria-hidden="true"><path d="M246.6 278.6c12.5-12.5 12.5-32.8 0-45.3l-128-128c-9.2-9.2-22.9-11.9-34.9-6.9s-19.8 16.6-19.8 29.6l0 256c0 12.9 7.8 24.6 19.8 29.6s25.7 2.2 34.9-6.9l128-128z"/></svg> : <svg viewBox="0 0 256 512" width="12" height="12" fill="currentColor" aria-hidden="true"><path d="M9.4 278.6c-12.5-12.5-12.5-32.8 0-45.3l128-128c9.2-9.2 22.9-11.9 34.9-6.9s19.8 16.6 19.8 29.6l0 256c0 12.9-7.8 24.6-19.8 29.6s-25.7 2.2-34.9-6.9l-128-128z"/></svg>}
          </button>
        </div>

        {/* Score pill + Plan badge */}
        {!collapsed && (
          <div style={{ background: '#EFF6FF', border: '1.5px solid #BFDBFE', borderRadius: 10, padding: '12px 14px', marginBottom: 16 }}>
            {/* b8a0: the pill shows the latest scan's overall_score — the
                AI Visibility Score. It previously carried a
                share-of-recommendation label, a different metric
                (score_history.recommendation_share) — the label now
                names the number it actually shows. */}
            <p style={{ fontSize: 11, fontWeight: 700, color: LGRAY, textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 4 }}>{effectiveNavKey === 'personal_pro' ? 'AI Name Recognition Score' : 'AI Visibility Score'}</p>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 4, marginBottom: 8 }}>
              {/* b8a1: the number follows the label — personal context
                  shows the personal scan's score (or — when none). */}
              <span style={{ fontSize: 28, fontWeight: 900, color: BLUE }}>{(effectiveNavKey === 'personal_pro' ? personalScore : score) !== null ? (effectiveNavKey === 'personal_pro' ? personalScore : score) : '—'}</span>
              <span style={{ fontSize: 12, color: LGRAY }}>/100</span>
            </div>
          </div>
        )}

        {/* Crystal-clear plan card */}
        {!collapsed && !planLoading && (() => {
          const displayPlan = isPersonalPage ? 'personal_pro' : (isAdmin ? rawPlan : plan);
          const meta = getPlanMeta(displayPlan);
          return (
            <div style={{ background: meta.isFree ? '#FFFBEB' : '#F5F3FF', border: `1.5px solid ${meta.isFree ? '#FDE68A' : '#DDD6FE'}`, borderRadius: 10, padding: '12px 14px', marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                <span style={{ fontSize: 16 }}>{meta.icon}</span>
                <span style={{ fontSize: 13, fontWeight: 800, color: NAVY }}>{getPlanLabel(effectiveNavKey)}</span>
              </div>
              <p style={{ fontSize: 11, color: meta.isFree ? '#92400E' : '#6D28D9', fontWeight: 600, margin: 0 }}>{meta.price}</p>
              {meta.isFree && (
                <Link href="/pricing" style={{ display: 'block', marginTop: 10, background: '#7C3AED', borderRadius: 8, padding: '8px 12px', fontSize: 12, fontWeight: 700, color: '#fff', textDecoration: 'none', textAlign: 'center' }}>
                  Upgrade Now <svg viewBox="0 0 448 512" width="12" height="12" fill="currentColor" aria-hidden="true"><path d="M438.6 278.6c12.5-12.5 12.5-32.8 0-45.3l-160-160c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3L338.8 224 32 224c-17.7 0-32 14.3-32 32s14.3 32 32 32l306.7 0L233.4 393.4c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0l160-160z"/></svg></Link>
              )}
            </div>
          );
        })()}
      </div>

      {/* Main nav */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '0 12px' }}>
        <NavGroups />
      </div>

      {/* User email + plan badge */}
      {!collapsed && userEmail && (
        <div style={{ padding: '8px 12px 0', borderTop: `1px solid ${BORDER}` }}>
          <p style={{ fontSize: 11, color: LGRAY, fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', marginBottom: 4 }}>
            {truncateEmail(userEmail)}
          </p>
          {!planLoading && (
            isAdmin ? (
              <a href="/admin/plan-switcher" style={{ display: 'inline-flex', alignItems: 'center', gap: 4, background: '#7c3aed', color: '#fff', borderRadius: 4, padding: '4px 10px', fontSize: 12, fontWeight: 600, textDecoration: 'none', cursor: 'pointer', marginBottom: 8 }}>
                {getPlanLabel(effectiveNavKey)} <svg viewBox="0 0 448 512" width="12" height="12" fill="currentColor" aria-hidden="true"><path d="M438.6 105.4c12.5 12.5 12.5 32.8 0 45.3l-256 256c-12.5 12.5-32.8 12.5-45.3 0l-128-128c-12.5-12.5-12.5-32.8 0-45.3s32.8-12.5 45.3 0L160 338.7 393.4 105.4c12.5-12.5 32.8-12.5 45.3 0z"/></svg>
                <span style={{ fontSize: 10 }}><svg viewBox="0 0 512 512" width="10" height="10" fill="currentColor" aria-hidden="true"><path d="M495.9 166.6c3.2 8.7 .5 18.4-6.4 24.6l-43.3 39.4c1.1 8.3 1.7 16.8 1.7 25.4s-.6 17.1-1.7 25.4l43.3 39.4c6.9 6.2 9.6 15.9 6.4 24.6c-4.4 11.9-9.7 23.3-15.8 34.3l-4.7 8.1c-6.6 11-14 21.4-22.1 31.2c-5.9 7.2-15.7 9.6-24.5 6.8l-55.7-17.7c-13.4 10.3-28.2 18.9-44 25.4l-12.5 57.1c-2 9.1-9 16.3-18.2 17.8c-13.8 2.3-28 3.5-42.5 3.5s-28.7-1.2-42.5-3.5c-9.2-1.5-16.2-8.7-18.2-17.8l-12.5-57.1c-15.8-6.5-30.6-15.1-44-25.4L83.1 425.9c-8.8 2.8-18.6 .3-24.5-6.8c-8.1-9.8-15.5-20.2-22.1-31.2l-4.7-8.1c-6.1-11-11.4-22.4-15.8-34.3c-3.2-8.7-.5-18.4 6.4-24.6l43.3-39.4C64.6 273.1 64 264.6 64 256s.6-17.1 1.7-25.4L22.4 191.2c-6.9-6.2-9.6-15.9-6.4-24.6c4.4-11.9 9.7-23.3 15.8-34.3l4.7-8.1c6.6-11 14-21.4 22.1-31.2c5.9-7.2 15.7-9.6 24.5-6.8l55.7 17.7c13.4-10.3 28.2-18.9 44-25.4l12.5-57.1c2-9.1 9-16.3 18.2-17.8C227.3 1.2 241.5 0 256 0s28.7 1.2 42.5 3.5c9.2 1.5 16.2 8.7 18.2 17.8l12.5 57.1c15.8 6.5 30.6 15.1 44 25.4l55.7-17.7c8.8-2.8 18.6-.3 24.5 6.8c8.1 9.8 15.5 20.2 22.1 31.2l4.7 8.1c6.1 11 11.4 22.4 15.8 34.3zM256 336a80 80 0 1 0 0-160 80 80 0 1 0 0 160z"/></svg></span>
              </a>
            ) : (
              <div style={{ display: 'inline-block', background: planCfg.badgeBg, border: `1px solid ${planCfg.badgeColor}44`, borderRadius: 100, padding: '2px 10px', marginBottom: 8 }}>
                <span style={{ fontSize: 10, fontWeight: 700, color: planCfg.badgeColor }}>{getPlanLabel(effectiveNavKey)} <svg viewBox="0 0 448 512" width="10" height="10" fill="currentColor" aria-hidden="true"><path d="M438.6 105.4c12.5 12.5 12.5 32.8 0 45.3l-256 256c-12.5 12.5-32.8 12.5-45.3 0l-128-128c-12.5-12.5-12.5-32.8 0-45.3s32.8-12.5 45.3 0L160 338.7 393.4 105.4c12.5-12.5 32.8-12.5 45.3 0z"/></svg></span>
              </div>
            )
          )}
        </div>
      )}

    </div>
  );

  // E1/E4: Inside the client area, render children bare — the client layout
  // supplies its own (isolated) sidebar. Never wrap clients in the agency nav.
  if (path.startsWith('/dashboard/client')) {
    return <>{children}</>;
  }

  // E1: Block rendering of the standard/agency dashboard until we've confirmed
  // the user is NOT an agency client (avoids a flash before redirect).
  if (!clientChecked && !path.startsWith('/dashboard/client')) {
    return (
      <div style={{ display: 'flex', minHeight: '100vh', background: BG, alignItems: 'center', justifyContent: 'center' }}>
        <p style={{ color: GRAY, fontSize: 15 }}>Loading…</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: BG }}>

      {/* Desktop sidebar */}
      <div className="desktop-only" style={{ display: 'flex' }}>
        <Sidebar />
      </div>

      {/* Mobile header */}
      <div className="mobile-only" style={{ position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100, background: W, borderBottom: `1px solid ${BORDER}`, padding: '12px 16px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <Link href="/" style={{ textDecoration: 'none', display: 'flex', alignItems: 'center', gap: 8 }}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/rankall-logo-dark.png" alt="RankAll" width={120} height={24} style={{ height: 24, width: 'auto', display: 'block' }} />
        </Link>
        <button onClick={() => setMobileOpen(o => !o)} style={{ background: 'none', border: `1.5px solid ${BORDER}`, borderRadius: 8, width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: NAVY, fontSize: 16 }}>
          {mobileOpen ? <svg viewBox="0 0 384 512" width="16" height="16" fill="currentColor" aria-hidden="true"><path d="M342.6 150.6c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L192 210.7 86.6 105.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3L146.7 256 41.4 361.4c-12.5 12.5-12.5 32.8 0 45.3s32.8 12.5 45.3 0L192 301.3 297.4 406.6c12.5 12.5 32.8 12.5 45.3 0s12.5-32.8 0-45.3L237.3 256 342.6 150.6z"/></svg> : <svg viewBox="0 0 448 512" width="16" height="16" fill="currentColor" aria-hidden="true"><path d="M0 96C0 78.3 14.3 64 32 64l384 0c17.7 0 32 14.3 32 32s-14.3 32-32 32L32 128C14.3 128 0 113.7 0 96zM0 256c0-17.7 14.3-32 32-32l384 0c17.7 0 32 14.3 32 32s-14.3 32-32 32L32 288c-17.7 0-32-14.3-32-32zM448 416c0 17.7-14.3 32-32 32L32 448c-17.7 0-32-14.3-32-32s14.3-32 32-32l384 0c17.7 0 32 14.3 32 32z"/></svg>}
        </button>
      </div>

      {/* Mobile drawer */}
      {mobileOpen && (
        <div className="mobile-only" style={{ position: 'fixed', inset: 0, zIndex: 99, background: 'rgba(0,0,0,0.3)' }} onClick={() => setMobileOpen(false)}>
          <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 240, background: SIDEBAR, padding: '72px 12px 20px', borderRight: `1px solid ${BORDER}`, overflowY: 'auto' }} onClick={e => e.stopPropagation()}>
            <NavGroups />
          </div>
        </div>
      )}

      {/* Main content */}
      <div style={{ flex: 1, minWidth: 0, paddingTop: 0, display: 'flex', flexDirection: 'column' }} className="dashboard-main">
        {/* Admin-only plan testing indicator */}
        {isAdmin && !planLoading && (
          <div style={{ background: '#7c3aed', color: '#fff', padding: '6px 16px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, fontSize: 12, fontWeight: 600, flexShrink: 0 }}>
            <span>🧪 Testing as: {getPlanLabel(navKey)}</span>
            <a href="/admin/plan-switcher" style={{ color: '#fff', textDecoration: 'underline', fontWeight: 700 }}>switch</a>
          </div>
        )}
        {/* b28h/b063: trial countdown — every dashboard page incl. billing
            (rendered once; it used to appear twice). */}
        {!planLoading && isTrialing && trialEndsAt && (
          <TrialCountdownBanner trialEndsAt={trialEndsAt} />
        )}
        <div style={{ flex: 1, minWidth: 0 }}>
          {children}
        </div>
      </div>

      <style>{`
        @media (max-width: 768px) {
          .desktop-only { display: none !important; }
          .mobile-only  { display: flex !important; }
          .dashboard-main { padding-top: 60px !important; padding-bottom: 88px; }
        }
        @media (min-width: 769px) {
          .mobile-only { display: none !important; }
        }
      `}</style>
    </div>
  );
}
